import {instantiate} from './wasm.js';
class TapeWorklet extends AudioWorkletProcessor {
 constructor(options){super();this.e=instantiate(options.processorOptions.module);if(!this.e.tape_init(sampleRate))throw Error('Unsupported audio rate');this.values=new Float32Array(37);this.elapsed=0;this.pool=[new Float32Array(1552),new Float32Array(1552),new Float32Array(1552)];this.port.onmessage=event=>this.message(event.data);this.port.postMessage({type:'ready',rate:sampleRate});}
 views(){if(this.memory!==this.e.memory.buffer){this.memory=this.e.memory.buffer;this.input=new Float32Array(this.memory,this.e.tape_input(),256);this.output=new Float32Array(this.memory,this.e.tape_output(),256);}}
 publish(){if(!this.pool.length)return;const ptr=this.e.tape_status();this.views();const target=this.pool.pop();target.set(new Float32Array(this.memory,ptr,1552));this.port.postMessage({type:'status',data:target.buffer},[target.buffer]);}
 message(m){if(m.type==='recycle'){if(m.data.byteLength===6208)this.pool.push(new Float32Array(m.data));return;}try{let result=true;if(m.type==='param'){if(!Number.isInteger(m.index)||m.index<0||m.index>36||!Number.isFinite(m.value))throw Error('Invalid parameter');this.values[m.index]=m.value;this.e.tape_set(m.index,m.value);}
 else if(m.type==='action'){result=!!this.e.tape_action(m.action);if(m.action===1&&result){this.values[8]=1;this.e.tape_set(8,1);}if(m.action===11&&result)this.values[0]=4;}
 else if(m.type==='note')this.e.tape_note(m.note,m.velocity??.8,m.on?1:0,m.drum?1:0);
 else if(m.type==='sustain')this.e.tape_sustain(m.on?1:0);
 else if(m.type==='drum')this.e.tape_drum(m.index);
 else if(m.type==='arm')this.e.tape_arm(m.track);
 else if(m.type==='seek')this.e.tape_seek(m.frame);
 else if(m.type==='select')this.e.tape_select(m.a,m.b);
 else if(m.type==='loop')this.e.tape_loop(m.bars);
 else if(m.type==='step')this.e.tape_step(m.row,m.step,m.on?1:0,m.note);
 else if(m.type==='snapshot'){this.e.tape_action(15);const meta=Array.from(new Float32Array(this.e.memory.buffer,this.e.tape_status(),16)),tracks=[],transfer=[];for(let t=0;t<4;t++){const n=this.e.tape_used(t,-1),audio=[];for(let c=0;c<2;c++){let data=new Float32Array(this.e.memory.buffer,this.e.tape_track(t,c),n).slice();audio.push(data);transfer.push(data.buffer);}tracks.push(audio);}let n=this.e.tape_sample_size(-1),sample=[];for(let c=0;c<2;c++){let data=new Float32Array(this.e.memory.buffer,this.e.tape_sample(c),n).slice();sample.push(data);transfer.push(data.buffer);}this.port.postMessage({type:'reply',id:m.id,result:{meta,loopStart:this.e.tape_loop_start(),tracks,sample,params:Array.from(this.values)}},transfer);this.publish();return;}
 else if(m.type==='restore'){const p=m.project,cap=this.e.tape_capacity();if(p.rate!==sampleRate||p.tracks.length!==4||p.tracks.some(a=>a.length!==2||a.some(c=>c.length>cap))||p.sample.some(c=>c.length>sampleRate*30))throw Error('Project exceeds tape capacity');this.e.tape_action(12);for(let t=0;t<4;t++){for(let c=0;c<2;c++)new Float32Array(this.e.memory.buffer,this.e.tape_track(t,c),cap).set(p.tracks[t][c]);this.e.tape_used(t,p.tracks[t][0].length);}this.e.tape_sample_size(p.sample[0].length);for(let c=0;c<2;c++)new Float32Array(this.e.memory.buffer,this.e.tape_sample(c),p.sample[c].length).set(p.sample[c]);p.params.forEach((v,i)=>{this.e.tape_set(i,v);this.values[i]=v;});for(let r=0;r<5;r++)for(let s=0;s<16;s++)this.e.tape_step(r,s,p.sequence[r][s]?1:0,p.notes[s]);this.e.tape_region(p.loopStart,p.loopEnd,p.position);this.e.tape_arm(p.armed);this.e.tape_action(16);}
 else if(m.type==='import'){this.e.tape_action(15);const meta=new Float32Array(this.e.memory.buffer,this.e.tape_status(),16);if(m.kind==='sample'){if(m.audio[0].length>sampleRate*30)throw Error('Sample exceeds 30 seconds');this.e.tape_sample_size(m.audio[0].length);for(let c=0;c<2;c++)new Float32Array(this.e.memory.buffer,this.e.tape_sample(c),m.audio[c].length).set(m.audio[c]);this.e.tape_set(0,4);this.values[0]=4;}else{const t=m.track,cap=this.e.tape_capacity(),start=Math.min(cap-1,Math.max(0,Math.floor(meta[0])));if(t<0||t>3||m.audio[0].length>sampleRate*60)throw Error('Invalid tape import');this.e.tape_checkpoint(t);const n=Math.min(cap-start,m.audio[0].length);for(let c=0;c<2;c++)new Float32Array(this.e.memory.buffer,this.e.tape_track(t,c),cap).set(m.audio[c].subarray(0,n),start);this.e.tape_used(t,Math.max(this.e.tape_used(t,-1),start+n));this.e.tape_region(0,Math.max(meta[4],start+n),start);}}
 if(m.id)this.port.postMessage({type:'reply',id:m.id,result});if(m.id||['action','arm','seek','loop','restore','import'].includes(m.type))this.publish();}catch(error){this.port.postMessage({type:'error',id:m.id,message:error.message});}}
 process(inputs,outputs){this.views();const out=outputs[0],incoming=inputs[0];if(!out?.[0])return true;for(let base=0;base<out[0].length;base+=128){const n=Math.min(128,out[0].length-base);for(let i=0;i<n;i++){this.input[i*2]=incoming?.[0]?.[base+i]??0;this.input[i*2+1]=incoming?.[1]?.[base+i]??this.input[i*2];}this.e.tape_render(n);for(let i=0;i<n;i++){out[0][base+i]=this.output[i*2];if(out[1])out[1][base+i]=this.output[i*2+1];}}this.elapsed+=out[0].length;if(this.elapsed>=sampleRate/24){this.elapsed=0;this.publish();}return true;}
}
registerProcessor('pxl-tape',TapeWorklet);
